import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"How to Use Hyperliquid Recovery Bot in Telegram","description":"Complete Telegram commands list (/start, /detect, /recovery) and interactive button guides for the recovery bot. Troubleshooting connection and input errors.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/bot-usage"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["meta",{"name":"keywords","content":"Telegram bot commands, recover bot instructions, interactive wallet recovery, recovery bot interface"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"How to Use Hyperliquid Recovery Bot in Telegram"}],["meta",{"property":"og:description","content":"Complete Telegram commands list (/start, /detect, /recovery) and interactive button guides for the recovery bot. Troubleshooting connection and input errors."}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/en/bot-usage"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"How to Use Hyperliquid Recovery Bot in Telegram"}],["meta",{"name":"twitter:description","content":"Complete Telegram commands list (/start, /detect, /recovery) and interactive button guides for the recovery bot. Troubleshooting connection and input errors."}]]},"headers":[],"relativePath":"en/bot-usage.md","filePath":"en/bot-usage.md","lastUpdated":null}'),i={name:"en/bot-usage.md"};function n(s,e,d,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="bot-usage" tabindex="-1">Bot Usage <a class="header-anchor" href="#bot-usage" aria-label="Permalink to &quot;Bot Usage&quot;">​</a></h1><p>This page explains key commands, the standard operating path, and how to read outputs.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/start</code></td><td>Open main menu</td></tr><tr><td><code>/detect</code></td><td>Start address detection</td></tr><tr><td><code>/recovery</code></td><td>Start asset recovery</td></tr></tbody></table><h2 id="standard-flow" tabindex="-1">Standard Flow <a class="header-anchor" href="#standard-flow" aria-label="Permalink to &quot;Standard Flow&quot;">​</a></h2><ol><li>Run <code>/start</code> to initialize session</li><li>Run <code>/detect</code> to inspect asset structure</li><li>Run <code>/recovery</code> and provide required inputs</li><li>Confirm plan and fee breakdown</li><li>Wait for the guided recovery process to finish and keep the transaction hashes for later checking if needed</li></ol><h2 id="interaction-notes" tabindex="-1">Interaction Notes <a class="header-anchor" href="#interaction-notes" aria-label="Permalink to &quot;Interaction Notes&quot;">​</a></h2><ul><li>Detection is read-only and does not require private key.</li><li>Recovery accepts private key or mnemonic.</li><li>No destination address input is required; funds return to the same source address on Arbitrum.</li><li>For lock/wait states, bot provides rerun timing guidance.</li></ul><h2 id="output-reading" tabindex="-1">Output Reading <a class="header-anchor" href="#output-reading" aria-label="Permalink to &quot;Output Reading&quot;">​</a></h2><p>Focus on these fields after execution:</p><ul><li><code>Recovered Amount</code></li><li><code>Actual Fees</code></li><li><code>Service Fee</code></li><li><code>Withdrawal Fees</code></li><li>Transaction hashes if you want to verify the transfers yourself</li></ul><p>Arrival to Arbitrum is asynchronous after withdrawal submission and may take several to more than ten minutes depending on Hyperliquid processing.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Skipping detection before recovery, which can make you miss locked or waiting assets</li><li>Treating estimated values as final actuals, even though prices may change slightly during execution</li><li>Not checking whether the source address can receive normally on Arbitrum, which may cause confusion when waiting for arrival</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./address-detection">Address Detection</a></li><li><a href="./asset-recovery">Asset Recovery</a></li><li><a href="./fee-and-settlement">Fee and Settlement</a></li><li><a href="./execution-status">Execution Status</a></li></ul>',16)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
